import ast, sys, os
for root, dirs, files in os.walk('.'):
    for name in files:
        if not name.endswith('.py'): continue
        path = os.path.join(root, name)
        tree = ast.parse(open(path).read(), path)
        imported = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    imported[(a.asname or a.name).split('.')[0]] = node.lineno
            elif isinstance(node, ast.ImportFrom):
                for a in node.names:
                    imported[a.asname or a.name] = node.lineno
        used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
        used |= {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
        for n in ast.walk(tree):
            if isinstance(n, ast.Attribute):
                v = n.value
                while isinstance(v, ast.Attribute): v = v.value
                if isinstance(v, ast.Name): used.add(v.id)
        text_src = open(path).read()
        unused = [k for k in imported if k not in used and ('%s.' % k) not in text_src.replace('import '+k,'')]
        if unused:
            print(path, 'possibly unused imports:', sorted(unused))
        # undefined global names
        defined = set()
        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                defined.add(node.name)
            elif isinstance(node, ast.Assign):
                for t in node.targets:
                    if isinstance(t, ast.Name): defined.add(t.id)
                    elif isinstance(t, (ast.Tuple, ast.List)):
                        defined |= {e.id for e in t.elts if isinstance(e, ast.Name)}
            elif isinstance(node, (ast.Import, ast.ImportFrom)):
                defined |= set(imported)
        builtins_names = set(dir(__builtins__)) | {'__name__','__file__','__doc__'}
        mods = set()
        for node in tree.body:
            if isinstance(node,(ast.Import,ast.ImportFrom)): pass
        missing = set()
        for n in ast.walk(tree):
            if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load):
                if n.id not in defined and n.id not in builtins_names:
                    # local variables?
                    missing.add(n.id)
        if missing:
            print(path, 'names not module-level (may be local):', sorted(missing)[:12])
PYEOF
